(function(){
 'use strict';
 const C=WordCampaign,J=WordJourney,Q=WordQuestions,E=VocabularyGames,A=ActionAudio;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const arts=['pixel-crystal-v1.webp','pixel-ember-v1.webp','pixel-eclipse-v1.webp'];
 let bridge,host,view='map',selected=1,region=0,paused=false,timer=null,clock=null,ticks=0;
 const state=()=>bridge.getState(),run=()=>state().campaign.draft,lesson=()=>LESSONS.find(l=>l.id===selected),hero=()=>WordBattles.hero(state().selectedHero||'mage');
 const active=()=>location.hash.includes('games/map')&&document.visibilityState!=='hidden';
 const stop=()=>{clearTimeout(timer);timer=null;};
 function applySkin(){document.querySelector('#game-app').dataset.heroSkin=state().campaign.skin;}
 function checkpoint(){if(clock!==null&&run()){run().elapsedMs=Math.min(86400000,run().elapsedMs+Math.max(0,Math.round(performance.now()-clock)));clock=null;}if(bridge)bridge.save();}
 function suspend(){stop();checkpoint();if(view==='battle')paused=true;}
 function heroArt(){const h=hero();return `<span class="hero-sprite hero-${h.art}" role="img" aria-label="${h.title}"></span>`;}
 function toolbar(inBattle=false){return `<div class="t-top"><button class="t-link" data-quest="${inBattle?'map':'exit'}">← ${inBattle?'Bản đồ':'Trò chơi'}</button><span class="t-save">${inBattle?'● Tiến độ từ đã được lưu':'50 chủ đề · 600 từ · 5 miền đất'}</span><div class="arena-tools">${inBattle?'<span id="quest-time" class="battle-time">'+time()+'</span>':`<span class="quest-total">${state().campaign.cleared.length}/50 <small>màn</small></span>`}<button class="t-icon" data-quest="sound" aria-label="${A.settings().muted?'Bật':'Tắt'} âm thanh">${A.settings().muted?'♪ ×':'♫'}</button>${GameScreen.control()}${inBattle?'<button class="t-icon" data-quest="pause" aria-label="Tạm dừng">Ⅱ</button>':''}</div></div>`;}
 function time(){const ms=(run()?.elapsedMs||0)+(clock===null?0:performance.now()-clock);return Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');}
 function map(){
  const s=state(),l=lesson(),p=C.progress(s,l),r=C.REGIONS[region],open=C.unlocked(s,l.id),cleared=s.campaign.cleared.includes(l.id),d=s.campaign.draft,resume=d&&d.lesson===l.id&&d.difficulty===(s.selectedDifficulty||'normal')&&['quiz','feedback'].includes(d.phase),reward=C.REWARDS[region],tier=WordBattles.difficulty(s.selectedDifficulty||'normal');
  host.innerHTML=`<section class="tactics-shell campaign-shell" style="--region:${r.color}">${toolbar()}<header class="quest-map-heading"><div><span class="t-kicker">HÀNH TRÌNH KÝ ỨC</span><h1>Đi từng bước. Nhớ từng từ.</h1></div><div class="quest-free"><button data-demo-mode="boss">⚔ Thẻ bài</button><button data-demo-mode="robot">◈ Robot</button></div></header><div class="quest-regions" role="group" aria-label="Chọn miền đất">${C.REGIONS.map((v,i)=>`<button data-quest="region" data-region="${i}" aria-label="Miền ${i+1}: ${v.name}" aria-pressed="${i===region}"><b>0${i+1}</b><span>${v.name}</span></button>`).join('')}</div><div class="quest-map-layout"><div class="quest-land"><div class="quest-land-banner"><div><span>${r.tag}</span><h2>${r.name}</h2><p>Màn ${region*10+1}–${region*10+10} · 12 từ mỗi màn</p></div><img src="/assets/${arts[r.art]}" alt="${r.boss}"></div><div class="quest-nodes" role="group" aria-label="Các chủ đề trong miền đất">${LESSONS.slice(region*10,region*10+10).map(n=>{const done=s.campaign.cleared.includes(n.id),unlocked=C.unlocked(s,n.id),np=C.progress(s,n);return `<button data-quest="node" data-node="${n.id}" class="quest-node ${done?'cleared':unlocked?'open':'locked'} ${n.id===selected?'selected':''}" aria-pressed="${n.id===selected}" aria-label="Màn ${n.id}: ${esc(n.title)} · ${done?'Đã hoàn thành':unlocked?'Đã mở':'Chưa mở'}"><b>${done?'✓':String(n.id).padStart(2,'0')}</b><span>${esc(n.title)}<small>${np.learned}/12 từ ${unlocked?'':'· 🔒'}</small></span></button>`;}).join('')}</div><div class="quest-reward-preview"><span>${reward.icon}</span><div><strong>${reward.name}</strong><small>Hoàn thành ${reward.at} màn để mở trang phục ${s.campaign.cleared.length>=reward.at?'· Đã mở ✓':''}</small></div></div></div><aside class="quest-detail"><div class="quest-detail-title"><span>MÀN ${String(l.id).padStart(2,'0')} ${cleared?'· ĐÃ VƯỢT QUA':open?'· ĐÃ MỞ':'· CHƯA MỞ'}</span><h2>${esc(l.title)}</h2><p>${esc(l.english)}</p></div><div class="quest-companion">${heroArt()}<div><strong>${hero().name}</strong><span>Đồng hành cùng bạn</span><div class="quest-heroes" role="group" aria-label="Bạn đồng hành">${WordBattles.HEROES.map(h=>`<button data-quest="hero" data-hero="${h.id}" aria-pressed="${hero().id===h.id}">${h.name}</button>`).join('')}</div></div></div><label class="quest-skin-label">Trang phục<select id="quest-skin" aria-label="Trang phục nhân vật">${[{id:'classic',name:'Nguyên bản',at:0},...C.REWARDS].map(v=>`<option value="${v.id}" ${v.id===s.campaign.skin?'selected':''} ${s.campaign.cleared.length<v.at?'disabled':''}>${v.name}${s.campaign.cleared.length<v.at?' · mở ở '+v.at+' màn':''}</option>`).join('')}</select></label><div class="quest-difficulty" role="group" aria-label="Độ khó câu hỏi">${WordBattles.DIFFICULTIES.map(v=>`<button data-quest="difficulty" data-difficulty="${v.id}" aria-pressed="${v.id===tier.id}">${v.name}</button>`).join('')}</div><p class="quest-format">${tier.level===1?'Anh → Việt · chọn nghĩa':tier.level===2?'Việt → Anh · chọn từ':'Điền từ vào câu · tự nhập tiếng Anh'}</p><div class="quest-node-progress"><span><b>${p.learned}/12</b> từ đã nhớ</span><div><i style="width:${p.learned/12*100}%"></i></div><small>${cleared?'Chủ đề đã hoàn thành, từ đã nhớ sẽ không ra lại.':open?'Nhớ đủ 12 từ để hạ boss và mở màn tiếp theo.':'Hoàn thành màn '+(l.id-1)+' để mở khu vực này.'}</small></div><button class="t-button quest-enter" data-quest="enter" ${!open||cleared?'disabled':''}>${cleared?'✓ Đã hoàn thành':!open?'🔒 Chưa mở':resume?'Tiếp tục màn này →':'Đối đầu boss →'}</button>${cleared&&l.id<50?'<button class="t-link" data-quest="next-node">Đến màn tiếp theo →</button>':''}</aside></div></section>`;
 }
 function questionView(){
  const s=state(),d=run(),f=d.feedback,id=f?.wordId||d.queue[0],w=WORDS.find(w=>w.id===id),q=Q.make(w,WORDS,d.seed+id.length,d.difficulty),m=J.status(s,id),show=q.kind==='meaning'||f;
  return `<section class="t-quiz quest-quiz question-${q.kind} ${f?(f.correct?'correct':'wrong'):''}" aria-label="Câu hỏi từ vựng"><div class="quiz-copy"><span class="t-kicker">${q.kind==='meaning'?'ANH → VIỆT':q.kind==='reverse'?'VIỆT → ANH':'ĐIỀN TỪ VÀO CÂU'}</span><h2>${esc(f?w.word:q.title)} ${show?`<button class="t-icon" data-quest="speak" data-word="${w.id}" aria-label="Nghe ${esc(w.word)}">♫</button>`:''}</h2>${show?`<span>${esc(w.ipa)} · ${esc(w.pos)}</span>`:''}${m.hard?`<span class="word-memory">◆ Khó nhớ · sai ${m.wrong} lần <b>Đúng ${m.streak}/3</b></span>`:''}${f?`<p class="answer-meaning">${f.correct?'✓ Chính xác!':'Cùng nhớ lại:'} ${esc(w.meaning)}</p><div class="answer-example">${esc(w.example)}<small>${esc(w.translation)}</small></div><p class="t-help">${f.correct?(m.mastered?'Một từ đã nhớ, một phong ấn được phá.':'Đã tăng chuỗi ghi nhớ. Từ này sẽ được ôn thêm.'):'Boss phản công! −'+({normal:20,hard:25,nightmare:34}[d.difficulty])+' máu.'}</p><button class="t-button" data-quest="advance">${f.correct?'Tiếp tục ngay · tự chuyển sau 2s':'Đã nhớ, tiếp tục'} →</button>`:q.kind==='cloze'?`<p class="cloze-sentence">${esc(q.sentence)}</p><p class="cloze-translation">${esc(q.hint)}</p>`:`<p>${q.hint}</p>`}</div>${f?'':q.kind==='cloze'?`<form class="word-entry" data-quest-typing><label for="quest-word-input">Từ hoặc cụm từ tiếng Anh</label><input id="quest-word-input" name="word" maxlength="100" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" enterkeyhint="done" required placeholder="Nhập từ còn thiếu…"><button class="t-button" type="submit">Phá phong ấn →</button><small>Không phân biệt chữ hoa, chữ thường.</small></form>`:`<div class="t-answers">${q.options.map((o,i)=>`<button data-quest="answer" data-answer="${o.id}"><span>${i+1}</span>${esc(o.label)}</button>`).join('')}</div>`}</section>`;
 }
 function battle(){
  const d=run(),l=LESSONS.find(l=>l.id===d.lesson),p=C.progress(state(),l),r=C.REGIONS[Math.floor((l.id-1)/10)];
  if(['won','lost'].includes(d.phase)){result();return;}
  host.innerHTML=`<section class="tactics-shell boss-game campaign-battle" style="--region:${r.color}">${toolbar(true)}<header class="t-heading"><div><span class="t-kicker">MÀN ${l.id} / 50 · ${WordBattles.difficulty(d.difficulty).name}</span><h1>${esc(l.title)}</h1></div><span class="quest-seals">${p.learned}/12 từ</span></header><div class="battle-layout"><section class="t-arena boss-arena stage-${r.art+1} ${d.feedback?(d.feedback.correct?'spell-cast':'spell-fizzle'):''}" aria-label="Boss của chủ đề"><div class="boss-name"><span class="t-kicker">12 PHONG ẤN KÝ ỨC</span><h2>${r.boss}</h2><div class="t-hp enemy"><i style="width:${p.left/12*100}%"></i></div><span class="quest-boss-left">${p.left} phong ấn còn lại</span></div><div class="hero-visual">${heroArt()}</div><img class="boss-visual" src="/assets/${arts[r.art]}" alt="${r.boss}"><div class="intent"><strong>${d.feedback?(d.feedback.correct?'✦ Phá phong ấn':'⚔ Boss phản công'):'Nhớ từ để hạ boss'}</strong></div><div class="hero-stats"><div><small>${hero().name.toUpperCase()}</small><div class="t-hp"><i style="width:${d.hp}%"></i></div><strong>♥ ${d.hp}/100</strong></div><span class="quest-penalty">Sai −${{normal:20,hard:25,nightmare:34}[d.difficulty]} máu</span></div></section><div class="play-panel">${questionView()}</div></div>${paused?'<div class="t-pause"><span>Ⅱ</span><h2>Nghỉ một chút.</h2><p>Từ đã học và ván chơi đã được lưu.</p><button class="t-button" data-quest="resume">Tiếp tục →</button><button class="t-link" data-quest="map">Về bản đồ</button></div>':''}</section>`;
  if(!paused&&d.phase==='feedback'&&d.feedback.correct){const id=d.id;timer=setTimeout(()=>{if(view==='battle'&&run()?.id===id&&active()&&!paused){checkpoint();C.advance(state());render();}},2000);}
 }
 function result(){
  const d=run(),l=LESSONS.find(l=>l.id===d.lesson),won=d.phase==='won',reward=C.REWARDS.find(r=>r.at===state().campaign.cleared.length&&won),p=C.progress(state(),l);
  host.innerHTML=`<section class="tactics-shell campaign-result">${toolbar(true)}<div class="quest-result-content"><span class="quest-result-mark">${won?'✦':'◈'}</span><span class="t-kicker">MÀN ${l.id} · ${esc(l.title)}</span><h1>${won?'Một miền ký ức đã sáng lên.':'Nghỉ rồi thử lại nhé.'}</h1><p>${won?(l.id===50?'Bạn đã hoàn thành cả 50 chủ đề và 600 từ.':'Boss đã bị đánh bại. Màn '+(l.id+1)+' đã mở!'):'Những từ đã nhớ được giữ lại. Lần tới chỉ còn từ chưa nhớ và từ từng sai.'}</p><div class="quest-result-stats"><span><b>${p.learned}/12</b>từ đã nhớ</span><span><b>${d.wrong}</b>lần trả lời sai</span><span><b>${time()}</b>thời gian</span></div>${reward?`<div class="quest-unlocked"><b>${reward.icon} Mở khóa ${reward.name}</b><p>Trang phục mới dùng được cho cả ba nhân vật.</p><button class="t-button" data-quest="equip" data-skin="${reward.id}">Mặc ngay</button></div>`:''}<div class="quest-result-actions"><button class="t-button" data-quest="${won?'next-node':'retry'}">${won?(l.id===50?'Về bản đồ':'Đến màn tiếp theo →'):'Thử lại với các từ còn lại →'}</button><button class="t-link" data-quest="map">Xem bản đồ</button></div></div></section>`;
 }
 function render(){stop();if(!host)return;applySkin();if(view==='map')map();else battle();if(view==='battle'&&!paused&&run()&&!['won','lost'].includes(run().phase))clock=performance.now();}
 function enter(retry=false){C.sync(state(),LESSONS);const d=run();if(!retry&&d?.lesson===selected&&d.difficulty===(state().selectedDifficulty||'normal')&&['quiz','feedback'].includes(d.phase)){view='battle';paused=false;render();return;}if(C.create(state(),lesson(),{difficulty:state().selectedDifficulty||'normal',seed:Math.floor(Math.random()*4294967295)})){view='battle';paused=false;A.play('fight');bridge.save();render();}}
 function respond(value){if(view!=='battle'||paused||!active())return;checkpoint();const answer=C.answer(state(),LESSONS,value);if(!answer)return;bridge.review(answer.id,answer.correct);A.play(answer.correct?'hit':'wrong');if(['won','lost'].includes(answer.phase)){const d=run(),rows=Object.entries(d.results).map(([id,r])=>({id,...r}));state().games=E.record(state(),d.id,{mode:'quest',at:Date.now(),score:rows.filter(r=>r.success).length*100,correct:rows.filter(r=>r.success&&!r.wrong).length,total:rows.length,seconds:Math.round(d.elapsedMs/1000),words:rows,won:answer.phase==='won',stage:d.lesson});A.play(answer.phase==='won'?'win':'lose');}bridge.save();render();}
 window.CampaignUI={init(callbacks){bridge=callbacks;C.init(state(),LESSONS);applySkin();setInterval(()=>{if(view==='battle'&&!paused&&active()){const el=document.querySelector('#quest-time');if(el)el.textContent=time();if(++ticks%5===0){checkpoint();clock=['won','lost'].includes(run()?.phase)?null:performance.now();}}},1000);},start(target){host=target;view='map';paused=false;clock=null;C.reconcile(state(),LESSONS);C.sync(state(),LESSONS);selected=state().campaign.selected;if(state().campaign.cleared.includes(selected))selected=LESSONS.find(l=>!state().campaign.cleared.includes(l.id))?.id||50;region=Math.floor((selected-1)/10);document.body.classList.add('game-active');bridge.save();render();},render,suspend,checkpoint,isActive:()=>view==='battle',reset(){suspend();host=null;view='map';},applySkin};
 document.addEventListener('click',e=>{
  const b=e.target.closest('[data-quest]');if(!b||b.disabled||!active())return;const a=b.dataset.quest;if(a!=='answer')A.play('click');
  if(a==='exit'){suspend();view='map';host=null;bridge.onExit();return;}
  if(a==='map'){checkpoint();view='map';paused=false;selected=run()?.lesson||selected;state().campaign.selected=selected;region=Math.floor((selected-1)/10);render();return;}
  if(a==='node'){selected=Number(b.dataset.node);state().campaign.selected=selected;bridge.save();render();return;}
  if(a==='region'){region=Number(b.dataset.region);selected=region*10+1;state().campaign.selected=selected;bridge.save();render();return;}
  if(a==='hero'){state().selectedHero=b.dataset.hero;bridge.save();render();return;}
  if(a==='difficulty'){state().selectedDifficulty=b.dataset.difficulty;bridge.save();render();return;}
  if(a==='sound'){A.toggle();checkpoint();render();return;}
  if(a==='enter'){enter();return;}if(a==='retry'){enter(true);return;}
  if(a==='answer'){respond(b.dataset.answer);return;}
  if(a==='advance'){checkpoint();C.advance(state());render();return;}
  if(a==='pause'){suspend();render();return;}if(a==='resume'){paused=false;render();return;}
  if(a==='speak'){bridge.speak(b.dataset.word);return;}
  if(a==='equip'){if(C.equip(state(),b.dataset.skin)){bridge.save();applySkin();bridge.notify('Đã mặc '+C.skins(state()).find(s=>s.id===b.dataset.skin).name);}return;}
  if(a==='next-node'){checkpoint();selected=Math.min(50,selected+1);state().campaign.selected=selected;region=Math.floor((selected-1)/10);view='map';paused=false;bridge.save();render();}
 });
 document.addEventListener('change',e=>{if(e.target.id==='quest-skin'&&C.equip(state(),e.target.value)){bridge.save();applySkin();A.play('select');}});
 document.addEventListener('submit',e=>{if(!e.target.matches('[data-quest-typing]'))return;e.preventDefault();const value=e.target.elements.word.value;if(value.trim())respond(value);});
 document.addEventListener('keydown',e=>{if(!active()||view!=='battle'||paused||run()?.phase!=='quiz'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(/^[1-4]$/.test(e.key))document.querySelectorAll('[data-quest="answer"]')[Number(e.key)-1]?.click();});
 document.addEventListener('visibilitychange',()=>{if(!active())suspend();else if(host&&view==='battle')render();});
 addEventListener('pagehide',checkpoint);
})();
